<script setup lang="ts">
import {newId} from '../ids'
const props=defineProps<{record:any;content:any;disabled?:boolean}>()
const emit=defineEmits<{(e:'change'):void}>()
const kinds=[['food','美食'],['sight','景点'],['transport','交通'],['other','其他']]
function changed(){emit('change')}
function addTravel(){if(props.disabled||props.record.travel)return;props.record.travel={start_date:null,end_date:null,activities:[]};changed()}
function addActivity(){if(props.disabled||!props.record.travel||props.record.travel.activities.length>=300)return;props.record.travel.activities.push({key:'activity_'+newId(),day:'',time:null,kind:'other',title:'',description:'',place_key:null,media_keys:[]});changed()}
function addFood(){if(props.disabled||props.record.foods.length>=100)return;const place=props.content.places.find((p:any)=>p.kind==='f');if(!place)return;props.record.foods.push({place_key:'',day:null,time:null,review:'',media_keys:[]});changed()}

</script>
<template><div class="exchange-structure" @input="changed" @change="changed"><details open><summary>标签、照片及封面归属</summary><label>标签（以中文顿号分隔）<input :value="record.tags.join('、')" maxlength="410" :disabled="disabled" @change="record.tags=($event.target as HTMLInputElement).value.split('、').map(v=>v.trim()).filter(Boolean)"></label><label>封面照片<select v-model="record.cover_key" :disabled="disabled"><option :value="null">不指定封面</option><option v-for="media in content.media" :key="media.key" :value="media.key">{{media.key}} · {{media.caption||media.alt||media.path||'现有照片'}}</option></select></label><fieldset :disabled="disabled"><legend>明确关联到本篇的图库照片</legend><label v-for="media in content.media" :key="media.key"><input v-model="record.media_keys" type="checkbox" :value="media.key">{{media.key}}</label></fieldset><p>在正文独立一行使用 <code v-pre>{{media:照片key}}</code> 设置准确插入位置；这里只调整本次导入，不改动现有媒体。</p></details>
<button v-if="!record.travel" type="button" class="quiet" :disabled="disabled" @click="addTravel">补充旅行安排（可选）</button><details v-if="record.travel" open><summary>旅行日期及活动</summary><p>未知日期请补充后校验；不会把文章展示日期当作旅行日期。</p><button type="button" class="quiet" :disabled="disabled||record.travel.activities.length>=300" @click="addActivity">添加候选活动</button><div class="mapping-fields"><label>实际出发日期<input :value="record.travel.start_date||''" type="date" :disabled="disabled" @input="record.travel.start_date=($event.target as HTMLInputElement).value||null"></label><label>实际返回日期（可留空）<input :value="record.travel.end_date||''" type="date" :disabled="disabled" @input="record.travel.end_date=($event.target as HTMLInputElement).value||null"></label></div><article v-for="activity in record.travel.activities" :key="activity.key" class="mapping-item"><h4>{{activity.title||'待补充活动'}}</h4><button type="button" class="quiet" :disabled="disabled" @click="record.travel.activities=record.travel.activities.filter((a:any)=>a!==activity);changed()">仅移除此候选活动</button><div class="mapping-fields"><label>活动日期<input v-model="activity.day" type="date" :disabled="disabled"></label><label>时间（可留空）<input :value="activity.time||''" type="time" :disabled="disabled" @input="activity.time=($event.target as HTMLInputElement).value||null"></label><label>活动类型<select v-model="activity.kind" :disabled="disabled"><option v-for="[key,name] in kinds" :key="key" :value="key">{{name}}</option></select></label><label>活动标题<input v-model="activity.title" maxlength="200" :disabled="disabled"></label><label>活动地点<select v-model="activity.place_key" :disabled="disabled"><option :value="null">不指定</option><option v-for="place in content.places" :key="place.key" :value="place.key">{{place.name}} · {{place.city}}</option></select></label></div><label>活动说明<textarea v-model="activity.description" rows="3" maxlength="10000" :disabled="disabled"/></label><fieldset :disabled="disabled"><legend>仅属于此活动的照片</legend><label v-for="media in content.media" :key="media.key"><input v-model="activity.media_keys" type="checkbox" :value="media.key">{{media.key}}</label></fieldset></article></details>
<button type="button" class="quiet" :disabled="disabled||record.foods.length>=100||!content.places.some((p:any)=>p.kind==='f')" @click="addFood">补充餐饮候选</button><p v-if="!content.places.some((p:any)=>p.kind==='f')">需要补充餐饮时，请先在下方地点候选中明确餐厅身份。</p><details v-if="record.foods.length" open><summary>餐饮、日期与照片归属</summary><article v-for="(food,index) in record.foods" :key="index" class="mapping-item"><h4>第 {{index+1}} 次餐饮记录</h4><button type="button" class="quiet" :disabled="disabled" @click="record.foods.splice(index,1);changed()">仅移除此餐饮候选</button><div class="mapping-fields"><label>餐厅<select v-model="food.place_key" :disabled="disabled"><option value="">请明确选择餐厅 / 分店</option><option v-for="place in content.places.filter((p:any)=>p.kind==='f')" :key="place.key" :value="place.key">{{place.name}} · {{place.city||'待分类'}}</option></select></label><label>实际用餐日期（未知可留空）<input :value="food.day||''" type="date" :disabled="disabled" @input="food.day=($event.target as HTMLInputElement).value||null"></label></div><label>用餐时间（可留空）<input :value="food.time||''" type="time" :disabled="disabled" @input="food.time=($event.target as HTMLInputElement).value||null"></label><label>本次点评<textarea v-model="food.review" rows="3" maxlength="10000" :disabled="disabled"/></label><fieldset :disabled="disabled"><legend>仅属于本次餐饮的照片</legend><label v-for="media in content.media" :key="media.key"><input v-model="food.media_keys" type="checkbox" :value="media.key">{{media.key}}</label></fieldset></article></details>
<details v-if="record.photos.length"><summary>照片日期与相册分组</summary><article v-for="photo in record.photos" :key="photo.media_key" class="mapping-item"><h4>{{photo.media_key}}</h4><div class="mapping-fields"><label>照片日期（未知可留空）<input :value="photo.taken_on||''" type="date" :disabled="disabled" @input="photo.taken_on=($event.target as HTMLInputElement).value||null"></label><label>相册分组<input v-model="photo.group_name" maxlength="100" :disabled="disabled"></label><label>照片地点<select v-model="photo.place_key" :disabled="disabled"><option :value="null">不指定</option><option v-for="place in content.places" :key="place.key" :value="place.key">{{place.name}} · {{place.city}}</option></select></label></div></article></details>
<details v-if="record.links.length"><summary>关联记录（仅建立关联，不修改对方）</summary><ul><li v-for="(link,index) in record.links" :key="index">{{link.record_key?'本次导入中的 '+link.record_key:'已选择的现有记录'}}<label>关系说明<input v-model="link.label" maxlength="80" :disabled="disabled"></label></li></ul></details></div></template>
<style scoped>.exchange-structure details{margin-block:16px;padding-block:12px;border-top:1px solid var(--ui-line)}.mapping-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,210px),1fr));gap:12px}.mapping-item{padding-block:12px;border-top:1px solid var(--ui-line)}.exchange-structure label{display:block}.exchange-structure fieldset{min-width:0}.exchange-structure input[type=checkbox]{width:auto}.exchange-structure textarea{width:100%;box-sizing:border-box}.exchange-structure code{overflow-wrap:anywhere}</style>
